previewCss:
.darma-loader-darma-b16-solar-sail-unfurl { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #fef3c7); width: var(--loader-size, 116px); height: var(--loader-size, 116px); position: relative; }
.darma-loader-darma-b16-solar-sail-unfurl span { position: absolute; left: 50%; top: 50%; width: 40%; height: 40%; background: repeating-linear-gradient(45deg, var(--accent) 0 12%, color-mix(in srgb, #fff 32%, var(--accent)) 0 24%); box-shadow: inset 0 0 0 2px var(--accent-2); animation: darma-loader-darma-b16-solar-sail-unfurl-sail-open calc(var(--loader-speed, 1s) * 3) cubic-bezier(.4, 0, .3, 1) infinite; }
.darma-loader-darma-b16-solar-sail-unfurl span:nth-of-type(1) { transform-origin: 0 100%; --to: translate(0, -100%); }
.darma-loader-darma-b16-solar-sail-unfurl span:nth-of-type(2) { transform-origin: 0 0; --to: translate(0, 0); animation-delay: calc(var(--loader-speed, 1s) * .12); }
.darma-loader-darma-b16-solar-sail-unfurl span:nth-of-type(3) { transform-origin: 100% 100%; --to: translate(-100%, -100%); animation-delay: calc(var(--loader-speed, 1s) * .24); }
.darma-loader-darma-b16-solar-sail-unfurl span:nth-of-type(4) { transform-origin: 100% 0; --to: translate(-100%, 0); animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b16-solar-sail-unfurl .darma-loader-darma-b16-solar-sail-unfurl__core { position: absolute; left: 43%; top: 43%; width: 14%; height: 14%; border-radius: 50%; background: var(--accent-2); box-shadow: 0 0 12px color-mix(in srgb, var(--accent-2) 70%, transparent); }
@keyframes darma-loader-darma-b16-solar-sail-unfurl-sail-open { 0%, 8% { transform: translate(-50%, -50%) scale(.06); opacity: 0; } 40%, 72% { transform: var(--to, none) scale(1); opacity: 1; } 96%, 100% { transform: translate(-50%, -50%) scale(.06); opacity: 0; } }

